import { resolve as resolve5 } from "node:path";
// ../mux-core/src/errors.ts
class MuxError extends Error {
  code;
  constructor(code, message, options) {
    super(message, options);
    this.code = code;
    this.name = "MuxError";
  }
}
// ../mux-core/src/backend.ts
import { spawn } from "node:child_process";

// ../mux-core/src/config.ts
import { constants } from "node:fs";
import { access, readFile, stat } from "node:fs/promises";
import { userInfo } from "node:os";
import { isAbsolute, join, resolve } from "node:path";
var openCodeConfigDir = "opencode";
var userConfigFile = "opencode-mux.json";
var userConfigName = `${openCodeConfigDir}/${userConfigFile}`;
function absoluteDir(value) {
  return value && isAbsolute(value) && !value.includes("\x00") ? value : undefined;
}
function userHome() {
  try {
    return userInfo().homedir;
  } catch {
    return;
  }
}
async function readUserConfig(home) {
  const homeDir = absoluteDir(home);
  if (!homeDir)
    return;
  const configDir = join(homeDir, ".config", openCodeConfigDir);
  const path = join(configDir, userConfigFile);
  let content;
  try {
    if (!(await stat(path)).isFile())
      throw new Error("expected a regular file");
    content = await readFile(path, "utf8");
  } catch (error) {
    const code = error.code;
    if (code === "ENOENT")
      return;
    throw new Error(`Could not read ${userConfigName} (${code ?? "expected a regular file"})`);
  }
  let value;
  try {
    value = JSON.parse(content);
  } catch {
    throw new Error(`${userConfigName} must contain valid JSON`);
  }
  const config = value && typeof value === "object" ? value : {};
  const { tmuxConfig = "tmux.conf", socketName } = config;
  if (typeof tmuxConfig !== "string" || !tmuxConfig.trim() || tmuxConfig.includes("\x00")) {
    throw new Error(`${userConfigName} requires tmuxConfig to be a non-empty path`);
  }
  if (typeof socketName !== "string" || !isDedicatedSocketName(socketName)) {
    throw new Error(`${userConfigName} requires a dedicated, non-default socketName`);
  }
  return { tmuxConfig: isAbsolute(tmuxConfig) ? tmuxConfig : resolve(configDir, tmuxConfig), socketName };
}
async function resolveMuxConfig(options, home = userHome()) {
  const userConfig = await readUserConfig(home);
  if (userConfig)
    return userConfig;
  return {
    tmuxConfig: options.tmuxConfig ?? options.backend?.tmuxConfig,
    socketName: options.socketName ?? options.backend?.socketName
  };
}
function isDedicatedSocketName(value) {
  return value !== undefined && value.trim() !== "" && !/^\.{1,2}$|^default$|[\\/\x00-\x1f\x7f]/i.test(value);
}
function assertTmuxConfigTarget({ kind, platform = process.platform, socketName, tmuxConfig }) {
  if (tmuxConfig === undefined)
    return;
  if (kind !== "tmux" || platform === "win32") {
    throw new Error("An explicit tmux.conf requires tmux on a non-Windows host");
  }
  if (!isDedicatedSocketName(socketName)) {
    throw new Error("An explicit tmux.conf requires a dedicated, non-default tmux socket name");
  }
  if (!isAbsolute(tmuxConfig) || tmuxConfig.includes("\x00")) {
    throw new Error("tmux.conf must be specified by an absolute path");
  }
}
async function validateTmuxBackendConfig(backend) {
  assertTmuxConfigTarget(backend);
  const path = backend.tmuxConfig;
  if (path === undefined)
    return;
  try {
    if ((await stat(path)).isFile()) {
      await access(path, constants.R_OK);
      return;
    }
  } catch (cause) {
    throw new Error(`tmux.conf must be a readable regular file: ${path}`, { cause });
  }
  throw new Error(`tmux.conf must be a readable regular file: ${path}`);
}

// ../mux-core/src/backend.ts
function createCommandRunner() {
  return (executable, args, { cwd, env, signal, timeoutMs } = {}) => new Promise((resolve, reject) => {
    const child = spawn(executable, args, {
      cwd,
      env,
      signal,
      timeout: timeoutMs,
      killSignal: "SIGKILL",
      stdio: ["ignore", "pipe", "pipe"],
      windowsHide: true
    });
    let stdout = "";
    let stderr = "";
    child.stdout.setEncoding("utf8").on("data", (chunk) => {
      stdout += chunk;
    });
    child.stderr.setEncoding("utf8").on("data", (chunk) => {
      stderr += chunk;
    });
    let error;
    child.once("error", (cause) => {
      error = cause;
    });
    child.once("close", (exitCode, exitSignal) => {
      if (error)
        reject(error);
      else
        resolve({ exitCode, stdout, stderr, signal: exitSignal ?? undefined });
    });
  });
}
async function detectMuxBackend({
  runner = createCommandRunner(),
  platform = process.platform,
  preferred,
  socketName,
  tmuxConfig
} = {}) {
  const fallback = platform === "win32" ? ["psmux", "tmux"] : ["tmux", "psmux"];
  const configured = tmuxConfig === undefined ? undefined : { kind: "tmux", executable: "tmux", platform, socketName, tmuxConfig };
  if (configured)
    await validateTmuxBackendConfig(configured);
  const kinds = configured ? ["tmux"] : preferred ? [preferred, ...fallback.filter((kind) => kind !== preferred)] : fallback;
  for (const kind of kinds) {
    try {
      if ((await runner(kind, ["-V"], { timeoutMs: 2000 })).exitCode === 0) {
        return configured ?? { kind, executable: kind, platform, socketName };
      }
    } catch (error) {
      const code = error.code;
      if (code !== "ENOENT" && code !== "EACCES")
        throw error;
    }
  }
  return null;
}
function quotePosixShell(value) {
  return `'${value.replaceAll("'", "'\\''")}'`;
}
function muxCommandArgs(backend, args) {
  const socket = backend.socketName ? ["-L", backend.socketName] : [];
  if (args[0] === "new-session" && backend.tmuxConfig !== undefined) {
    assertTmuxConfigTarget(backend);
    return [...socket, "-f", backend.tmuxConfig, ...args];
  }
  return [...socket, ...args];
}
function useCmd(backend) {
  return (backend.platform ?? process.platform) === "win32" || backend.kind === "psmux";
}
function supportsPosixMuxFeatures(backend) {
  return !useCmd(backend);
}
function quoteCmdArg(value) {
  if (/["%\r\n\0]/.test(value))
    throw new Error("Unsupported character in cmd.exe argument");
  return `"${value.replace(/\\+$/, "$&$&")}"`;
}
function wrapShellCommand(backend, command, channel, exitFilePrefix) {
  const direct = command.endsWith(";") ? `${command}${useCmd(backend) ? " " : `
`}` : command;
  const executable = backend.executable ?? backend.kind;
  if (exitFilePrefix && supportsPosixMuxFeatures(backend)) {
    const signal = channel ? `${[executable, ...muxCommandArgs(backend, ["wait-for", "-S", channel])].map(quotePosixShell).join(" ")} 2>/dev/null; ` : "";
    return [
      "sh",
      "-lc",
      `trap ':' INT; sh -lc ${quotePosixShell(command)}; __rc=$?; ` + `__oc_exit=${quotePosixShell(exitFilePrefix)}$$.txt; ` + 'if __oc_tmp=$(mktemp "${__oc_exit}.XXXXXX"); then ' + `if ! { printf '%s\\n' "$__rc" > "$__oc_tmp" && mv -f "$__oc_tmp" "$__oc_exit"; }; then rm -f "$__oc_tmp"; fi; fi; ` + signal + 'if [ -n "$SHELL" ] && [ -x "$SHELL" ]; then exec "$SHELL" -i; ' + "elif [ -x /bin/bash ]; then exec /bin/bash -i; else exec /bin/sh -i; fi"
    ];
  }
  if (!channel)
    return useCmd(backend) ? ["cmd.exe", "/d", "/c", direct] : ["sh", "-lc", direct];
  const args = muxCommandArgs(backend, ["wait-for", "-S", channel]);
  if (useCmd(backend)) {
    if (/["%!^\r\n]/.test(command) || [executable, ...args].some((arg) => /["%!\r\n\0]/.test(arg))) {
      return ["cmd.exe", "/d", "/c", direct];
    }
    const signal = [executable, ...args].map(quoteCmdArg).join(" ");
    return [
      "cmd.exe",
      "/d",
      "/v:on",
      "/c",
      `cmd.exe /d /v:off /s /c "${command}" & set "__oc_rc=!errorlevel!" & ${signal} & exit /b !__oc_rc!`
    ];
  }
  const signal = [executable, ...args].map(quotePosixShell).join(" ");
  return ["sh", "-lc", `sh -lc ${quotePosixShell(command)}; __rc=$?; ${signal}; exit "$__rc"`];
}
function buildAttachCommand(backend, sessionName) {
  const executable = backend.executable ?? backend.kind;
  const args = muxCommandArgs(backend, ["attach-session", "-t", `=${sessionName}`]);
  if (useCmd(backend)) {
    return `cmd.exe /d /v:off /s /c "${[executable, ...args].map(quoteCmdArg).join(" ")}"`;
  }
  return [executable, ...args].map(quotePosixShell).join(" ");
}
function stripAnsi(text) {
  return text.replace(/(?:\x1b\]|\x9d)[^\x07\x1b\x9c]*(?:\x07|\x1b\\|\x9c)/g, "").replace(/(?:\x1b[P^_X]|[\x90\x98\x9e\x9f])[^\x1b\x9c]*(?:\x1b\\|\x9c)/g, "").replace(/(?:\x1b\[|\x9b)[0-?]*[ -/]*[@-~]|\x1b[ -/]*[@-_]/g, "");
}
